// Convierte la salida del Router en un objeto limpio y aplica fallback a INCIERTO
const raw = String($input.first().json.output || '');
const trig = $('Chat Trigger').first().json;
const VALIDAS = ['PEDIDO', 'RECLAMO', 'FUERA_DE_AMBITO', 'INCIERTO'];
let categoria = 'INCIERTO';
let motivo = 'No se pudo interpretar la clasificación del Router';
let nombre = '';
try {
  const match = raw.match(/\{[\s\S]*\}/);
  const parsed = JSON.parse(match ? match[0] : raw);
  categoria = String(parsed.categoria || '').toUpperCase().trim();
  motivo = parsed.motivo || '';
  nombre = String(parsed.nombre_detectado || '').trim();
} catch (e) { /* queda INCIERTO */ }
if (!VALIDAS.includes(categoria)) categoria = 'INCIERTO';
if (nombre.length > 60 || /no informado/i.test(nombre)) nombre = '';
return [{ json: { categoria, motivo, nombre_detectado: nombre, sessionId: trig.sessionId, mensaje: trig.chatInput } }];

// Unifica la respuesta de cualquier rama y arma la fila de trazabilidad
const entrada = $input.first().json;
const r = entrada.status ? entrada : $('Preparar Escape').first().json;
const p = $('Parsear Intención').first().json;
const seDelego = ['PEDIDO', 'RECLAMO'].includes(p.categoria);
return [{
  json: {
    Fecha: $now.setZone('America/Argentina/Buenos_Aires').toFormat('yyyy-MM-dd HH:mm:ss'),
    Session_ID: p.sessionId,
    Categoria: p.categoria,
    Motivo_Router: p.motivo,
    Worker: r.worker,
    Parametros_Enviados: seDelego ? JSON.stringify({ sessionId: p.sessionId, mensaje: p.mensaje }) : '-',
    Status: r.status,
    Accion: r.data?.accion || '',
    Respuesta: r.data?.respuesta || '',
    Error: r.error || '',
    Mensaje: p.mensaje
  }
}];

// Calcula el nuevo estado de la memoria de largo plazo (sin transcripciones)
const ctx = $('Contexto de Sesión').first().json;
const p = $('Parsear Intención').first().json;
const c = $('Consolidar Resultado').first().json;
const accion = String(c.Accion || '');
const ESTABLES = ['Pedido registrado', 'Reclamo abierto', 'Escalado a supervisor'];
let estado;
if (accion.startsWith('registro_en_planilla')) estado = 'Pedido registrado';
else if (accion.startsWith('reclamo_registrado')) estado = 'Reclamo abierto';
else if (accion === 'escalado_supervisor') estado = 'Escalado a supervisor';
else if (accion === 'contingencia') estado = 'Error técnico';
else estado = ESTABLES.includes(ctx.last_status) ? ctx.last_status : 'En curso';
const sinResumir = Number(ctx.sin_resumir || 0) + 1;
return [{
  json: {
    record_id: ctx.record_id,
    Nombre_Usuario: p.nombre_detectado || ctx.nombre_registrado || '',
    Estado_Caso: estado,
    Total_Mensajes: Number(ctx.total_mensajes || 0) + 1,
    Mensajes_Sin_Resumir: sinResumir,
    requiere_resumen: sinResumir > 5
  }
}];

// Arma el historial reciente de la sesión a partir del log de Trazabilidad
const filas = $input.all().map(i => i.json).filter(r => r.Mensaje || r.Respuesta);
const ultimas = filas.slice(-12);
const historial = ultimas
  .map(r => 'Cliente: ' + (r.Mensaje || '(sin texto)') + '\nAqua: ' + (r.Respuesta || '(sin respuesta)'))
  .join('\n\n');
return [{ json: { historial: historial || 'Sin historial disponible.', turnos: ultimas.length } }];

// Valida el JSON del resumidor; si falla, conserva el resumen anterior y reintenta en el próximo turno
const raw = String($input.first().json.output || '');
const ctx = $('Contexto de Sesión').first().json;
const mem = $('Preparar Memoria').first().json;
let obj = null;
try {
  const m = raw.match(/\{[\s\S]*\}/);
  obj = JSON.parse(m ? m[0] : raw);
} catch (e) { obj = null; }
const ok = !!obj && typeof obj.asunto_principal === 'string' && Array.isArray(obj.puntos_clave)
  && typeof obj.accion_requerida === 'string';
if (!ok) {
  return [{ json: { record_id: ctx.record_id, valido: false,
    Resumen_Consolidado: ctx.prev_resumen, Datos_Clave: ctx.prev_datos, Resumen_JSON: ctx.prev_json,
    Mensajes_Sin_Resumir: mem.Mensajes_Sin_Resumir } }];
}
const resumen = {
  asunto_principal: obj.asunto_principal.trim(),
  puntos_clave: obj.puntos_clave.map(x => String(x).trim()).filter(Boolean).slice(0, 5),
  accion_requerida: obj.accion_requerida.trim()
};
return [{ json: { record_id: ctx.record_id, valido: true,
  Resumen_Consolidado: resumen.asunto_principal + ' | Acción requerida: ' + resumen.accion_requerida,
  Datos_Clave: resumen.puntos_clave.join(' · '),
  Resumen_JSON: JSON.stringify(resumen),
  Mensajes_Sin_Resumir: 0 } }];

