// Interpreta el JSON del agente con valores de respaldo seguros
const raw = String($input.first().json.output || '');
let r = {};
try { const m = raw.match(/\{[\s\S]*\}/); r = JSON.parse(m ? m[0] : raw); } catch (e) { r = {}; }
const CATS = ['PEDIDO', 'RECLAMO', 'CONSULTA', 'OTRO'];
const categoria = CATS.includes(String(r.categoria || '').toUpperCase()) ? String(r.categoria).toUpperCase() : 'OTRO';
return [{ json: {
  categoria,
  nombre_cliente: String(r.nombre_cliente || '').trim().slice(0, 80),
  resumen: String(r.resumen || 'Sin resumen').trim().slice(0, 300),
  borrador_respuesta: String(r.borrador_respuesta || '').trim(),
  requiere_atencion_humana: r.requiere_atencion_humana === true || categoria === 'RECLAMO',
  ia_valida: !!r.borrador_respuesta
} }];
